def main():
    print(f"Translating {len(DOC_FILES)} markdown documentation files to German...")
    for rel_path in DOC_FILES:
        build_localized_file(rel_path, "de", TRANSLATIONS_DE)

    # Verification
    docs_dir = os.path.join(REPO_ROOT, "docs")
    de_dir = os.path.join(docs_dir, "de")
    generated_files = []
    for root, dirs, files in os.walk(de_dir):
        for file in files:
            if file.endswith(".md"):
                rel_path = os.path.relpath(os.path.join(root, file), de_dir)
                generated_files.append(rel_path.replace("\\", "/"))

    generated_files.sort()
    print(f"Successfully generated {len(generated_files)} German documentation files in docs/de/.")
    if len(generated_files) == len(DOC_FILES):
        print("Verification passed: All 59 documentation files generated successfully.")
    else:
        print(f"Verification mismatch: Expected {len(DOC_FILES)} files, but found {len(generated_files)}.")

if __name__ == "__main__":
    main()
